        [Str.HelpStartH] = "Per iniziare",
        [Str.HelpStartBody] = "Apri Collega e inserisci l'ID di sincronizzazione e la password per collegare questo dispositivo. I segnalibri vengono cifrati sul dispositivo prima del caricamento, quindi il server non li vede mai in chiaro. Una password dimenticata non si può recuperare: conservala con cura.",
